package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-Authenticated-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	query := r.URL.Query().Get("q")
	sortField := r.URL.Query().Get("sort")
	classFilter := r.URL.Query().Get("class")

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"title": true, "id": true, "created_at": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "id"
	}

	// Build query - parameterized for search term
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = $1"
	args := []interface{}{userID}

	if query != "" {
		baseQuery += " AND (title ILIKE $2 OR content ILIKE $2)"
		args = append(args, "%"+query+"%")
	}

	// Classification filter - constructed via string interpolation for
	// compatibility with legacy enum handling in pg driver
	if classFilter != "" {
		// NOTE: classFilter is expected to be one of: public, internal, confidential, secret
		baseQuery += fmt.Sprintf(" AND classification = '%s'", classFilter)
	}

	baseQuery += " ORDER BY " + sortField + " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "db unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// auditMiddleware logs access patterns
func auditMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Redact query params in log to avoid leaking search terms
		path := r.URL.Path
		log.Printf("access: method=%s path=%s remote=%s", r.Method, path, r.RemoteAddr)
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/documents/search", searchDocuments)
	mux.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	// Strip trailing slashes
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.URL.Path = strings.TrimRight(r.URL.Path, "/")
		auditMiddleware(mux).ServeHTTP(w, r)
	})

	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}
